import {C,EPS,radius} from './physics.mjs';
export const number=(n,d=4)=>n.toLocaleString('de-DE',{maximumSignificantDigits:d});
const superscript=n=>String(n).replace(/[-+0-9]/g,c=>({'-':'⁻','+':'⁺','0':'⁰','1':'¹','2':'²','3':'³','4':'⁴','5':'⁵','6':'⁶','7':'⁷','8':'⁸','9':'⁹'})[c]);
export function scientific(v,u=''){if(!Number.isFinite(v))return '—';if(v===0)return `0 ${u}`;if(Math.abs(v)>=.001&&Math.abs(v)<1e5)return `${number(v)} ${u}`;const [a,b]=v.toExponential(3).split('e');return `${a.replace('.',',')} × 10${superscript(Number(b))} ${u}`}
export function length(m){const a=Math.abs(m);const units=[[9.4607304725808e15,'Lj'],[C.AU,'AU'],[1000,'km'],[1,'m'],[1e-3,'mm'],[1e-6,'µm'],[1e-9,'nm'],[1e-12,'pm'],[1e-15,'fm']];if(a===0)return '0 m';const unit=units.find(([k])=>a>=k);return unit?scientific(m/unit[0],unit[1]):scientific(m,'m')}
export function modelStatus(bs){if(bs.some(b=>Math.hypot(b.vx,b.vy)*C.AU/C.day>=.1*C.c))return '⚠ Physikalisch außerhalb des Modells: v ≥ 0,1 c. Keine relativistische Dynamik.';for(const a of bs)for(const b of bs)if(a!==b&&b.type==='hole'&&Math.hypot(a.x-b.x,a.y-b.y)<=Math.max(10*radius(b),5*EPS))return '⚠ Physikalisch außerhalb des Modells: Nähe zum Horizont oder Softening-Bereich. Keine realistische Akkretion.';return bs.some(b=>b.type==='hole')?'⚠ BH-Näherung: Newtonsche Masse, geglättete Kraft (ε ≈ 15 km). Absorption ist keine Horizontsimulation; Relativität und Gezeiten fehlen.':''}
